//! Frozen bit witness for the M3b consolidation.
//!
//! Every case reduces a construction, cycle or solve result to a 64-bit FNV-1a
//! digest of its exact values (hierarchy graphs, transfers, repeats, terminal
//! factor solves, cycle outputs, solutions and PCG diagnostics). Digests were
//! generated by the pre-consolidation API (CMG 03a26041) for each feature
//! combination and are compared here, so a consolidated implementation must
//! reproduce the old bits exactly. Set `CMG_FROZEN_WRITE=1` to regenerate the
//! current feature combination's section; never regenerate to accept a change.

use cmg::*;
use std::collections::BTreeMap;
use std::fmt::Write as _;

const FIXTURE: &str = "tests/fixtures/frozen_bits.txt";

struct Digest(u64);

impl Digest {
    fn new() -> Self {
        Self(0xcbf2_9ce4_8422_2325)
    }
    fn word(&mut self, value: u64) {
        for byte in value.to_le_bytes() {
            self.0 ^= u64::from(byte);
            self.0 = self.0.wrapping_mul(0x0100_0000_01b3);
        }
    }
    fn usize(&mut self, value: usize) {
        self.word(value as u64);
    }
    fn f64(&mut self, value: f64) {
        self.word(value.to_bits());
    }
    fn values(&mut self, values: &[f64]) {
        self.usize(values.len());
        values.iter().for_each(|&value| self.f64(value));
    }
    fn counts(&mut self, values: &[usize]) {
        self.usize(values.len());
        values.iter().for_each(|&value| self.usize(value));
    }
    fn diagnostics(&mut self, diagnostics: PcgDiagnostics) {
        self.usize(diagnostics.iterations());
        for value in [
            diagnostics.initial_residual_norm(),
            diagnostics.residual_norm(),
            diagnostics.relative_residual(),
            diagnostics.backward_error(),
            diagnostics.tolerance(),
            diagnostics.rhs_projection_norm(),
        ] {
            self.f64(value);
        }
        self.usize(diagnostics.restarts());
    }
}

fn features() -> String {
    let mut names = Vec::new();
    if cfg!(feature = "parallel") {
        names.push("parallel");
    }
    if cfg!(feature = "experimental-components") {
        names.push("experimental-components");
    }
    if cfg!(feature = "profiling") {
        names.push("profiling");
    }
    if cfg!(feature = "cycle-profiling") {
        names.push("cycle-profiling");
    }
    if names.is_empty() {
        "default".to_owned()
    } else {
        names.join("+")
    }
}

struct Lcg(u64);

impl Lcg {
    fn next(&mut self) -> u64 {
        self.0 = self
            .0
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        self.0 >> 11
    }
    fn below(&mut self, bound: usize) -> usize {
        (self.next() % bound as u64) as usize
    }
    fn weight(&mut self) -> f64 {
        // Dyadic weights spanning six binades keep duplicates and ties live.
        (1 + self.below(64)) as f64 / 8.0 * [1.0, 0.5, 4.0, 1.0 / 64.0][self.below(4)]
    }
}

/// Path with chords, a weak edge and a second component plus isolates.
fn chain_edges() -> (usize, Vec<(usize, usize, f64)>) {
    let mut edges = Vec::new();
    for v in 1..300 {
        let weight = if v == 150 {
            1.0 / 4096.0
        } else {
            1.0 + (v % 7) as f64 / 4.0
        };
        edges.push((v - 1, v, weight));
        if v >= 3 && v % 5 == 0 {
            edges.push((v - 3, v, 0.125));
        }
    }
    for v in 301..360 {
        edges.push((v - 1, v, 2.0 + (v % 3) as f64));
    }
    (364, edges)
}

/// Random multigraph with duplicate edges, both endpoint orders and isolates.
fn random_edges(vertices: usize, count: usize, seed: u64) -> (usize, Vec<(usize, usize, f64)>) {
    let mut rng = Lcg(seed);
    let mut edges = Vec::with_capacity(count);
    while edges.len() < count {
        let u = rng.below(vertices - 7);
        let v = if rng.below(4) == 0 {
            (u + 1 + rng.below(3)) % (vertices - 7)
        } else {
            rng.below(vertices - 7)
        };
        if u != v {
            let weight = rng.weight();
            edges.push((u, v, weight));
            if rng.below(9) == 0 {
                edges.push((v, u, weight * 0.75));
            }
        }
    }
    edges.truncate(count);
    (vertices, edges)
}

/// Weighted grid above every parallel setup threshold.
fn grid_edges(rows: usize, columns: usize) -> (usize, Vec<(usize, usize, f64)>) {
    let mut edges = Vec::new();
    let id = |r: usize, c: usize| r * columns + c;
    for r in 0..rows {
        for c in 0..columns {
            if c + 1 < columns {
                edges.push((id(r, c), id(r, c + 1), 1.0 + ((r * 7 + c) % 5) as f64 / 8.0));
            }
            if r + 1 < rows {
                edges.push((id(r, c), id(r + 1, c), 0.5 + ((r + 3 * c) % 11) as f64 / 16.0));
            }
        }
    }
    (rows * columns, edges)
}

fn graph_digest(digest: &mut Digest, graph: &Laplacian) {
    digest.usize(graph.vertex_count());
    digest.usize(graph.edge_count());
    for edge in graph.edges() {
        digest.usize(edge.u());
        digest.usize(edge.v());
        digest.f64(edge.weight());
    }
    digest.values(graph.diagonal());
    digest.usize(graph.matrix_nnz());
    digest.f64(graph.operator_norm_bound());
}

fn compatible_rhs(graph: &Laplacian, seed: u64) -> Vec<f64> {
    let mut rng = Lcg(seed);
    let known: Vec<_> = (0..graph.vertex_count())
        .map(|_| rng.below(2001) as f64 / 1000.0 - 1.0)
        .collect();
    graph.matvec(&known).unwrap()
}

fn raw_rhs(graph: &Laplacian, seed: u64) -> Vec<f64> {
    // Compatible signal plus exact component-constant drift for apply_into.
    let mut rhs = compatible_rhs(graph, seed);
    let components = Components::from_laplacian(graph);
    for (value, &label) in rhs.iter_mut().zip(components.labels()) {
        *value += 1e-14 * (label % 3) as f64;
    }
    rhs
}

fn preconditioner_digest(graph: &Laplacian, preconditioner: &CmgPreconditioner) -> u64 {
    let mut digest = Digest::new();
    let hierarchy = preconditioner.hierarchy();
    let report = hierarchy.report();
    digest.usize(report.terminal_reason() as usize);
    digest.counts(report.vertex_counts());
    digest.counts(report.matrix_nonzeros());
    digest.usize(report.cumulative_coarsened_nonzeros());
    for level in hierarchy.levels() {
        graph_digest(&mut digest, level.graph());
        digest.values(level.inverse_diagonal());
        digest.usize(level.repeat());
        if let Some(aggregation) = level.aggregation() {
            digest.counts(aggregation.labels());
            digest.usize(aggregation.coarse_dimension());
        }
        #[cfg(feature = "experimental-components")]
        if let Some(pruned) = level.pruned_transfer() {
            digest.usize(pruned.coarse_dimension());
            digest.usize(pruned.represented_coarse_dimension());
            for &(left, right) in pruned.entries() {
                digest.word(u64::from(left) << 32 | u64::from(right));
            }
        }
    }
    digest.counts(preconditioner.repeat_counts());
    if let Some(factor) = preconditioner.terminal_factor() {
        digest.counts(factor.anchors());
        digest.counts(factor.permutation());
        digest.usize(factor.active_dimension());
        digest.usize(factor.factor_nonzeros());
        let terminal = hierarchy.levels().last().unwrap().graph();
        digest.values(&factor.solve(&compatible_rhs(terminal, 91)).unwrap());
    }
    let mut workspace = preconditioner.try_workspace().unwrap();
    let mut output = vec![0.0; graph.vertex_count()];
    for seed in [1, 2, 3] {
        preconditioner
            .apply_compatible_into(&compatible_rhs(graph, seed), &mut output, &mut workspace)
            .unwrap();
        digest.values(&output);
    }
    preconditioner
        .apply_into(&raw_rhs(graph, 4), &mut output, &mut workspace)
        .unwrap();
    digest.values(&output);
    digest.0
}

fn options(direct_threshold: usize) -> CmgOptions {
    CmgOptions {
        direct_threshold,
        ..CmgOptions::default()
    }
}

fn pcg_options() -> PcgOptions {
    PcgOptions {
        relative_tolerance: 1e-10,
        max_iterations: 500,
        ..PcgOptions::default()
    }
}

#[cfg(feature = "parallel")]
fn executor(threads: usize) -> ParallelExecutor {
    ParallelExecutor::new(ParallelOptions {
        threads,
        min_parallel_len: 64,
        reduction_chunk_size: 256,
        ..ParallelOptions::default()
    })
    .unwrap()
}

#[cfg(feature = "experimental-components")]
fn component_options(bits: usize) -> ComponentBuildOptions {
    ComponentBuildOptions {
        prune_coarse_isolates: bits & 1 != 0,
        preserve_unpruned_stopping: bits & 2 != 0,
        factor_terminal_components: bits & 4 != 0,
    }
}

fn builders(
    cases: &mut BTreeMap<String, u64>,
    name: &str,
    graph: &Laplacian,
    options: CmgOptions,
    large: bool,
) {
    let mut record = |case: String, preconditioner: CmgPreconditioner| {
        cases.insert(format!("{name}/{case}"), preconditioner_digest(graph, &preconditioner));
    };
    record("build".into(), CmgPreconditioner::build(graph, options).unwrap());
    record(
        "build_serial_budget".into(),
        CmgPreconditioner::build_serial_with_budget(graph, options, usize::MAX).unwrap(),
    );
    #[cfg(feature = "parallel")]
    for threads in [1, 4] {
        let executor = executor(threads);
        record(
            format!("build_executor_t{threads}"),
            CmgPreconditioner::build_with_executor(graph, options, &executor).unwrap(),
        );
        record(
            format!("build_executor_budget_t{threads}"),
            CmgPreconditioner::build_with_executor_and_cmg_budget(
                graph,
                options,
                &executor,
                usize::MAX,
            )
            .unwrap(),
        );
    }
    #[cfg(feature = "experimental-components")]
    for bits in 0..8 {
        let experiment = component_options(bits);
        record(
            format!("component{bits}"),
            CmgPreconditioner::build_component_experiment(graph, options, experiment).unwrap(),
        );
        record(
            format!("component{bits}_serial_budget"),
            CmgPreconditioner::build_component_experiment_serial_with_budget(
                graph,
                options,
                experiment,
                usize::MAX,
            )
            .unwrap(),
        );
        if !large || bits == 7 {
            record(
                format!("component{bits}_controlled"),
                CmgPreconditioner::build_component_experiment_serial_controlled(
                    graph,
                    options,
                    experiment,
                    usize::MAX,
                    &|| false,
                )
                .unwrap(),
            );
        }
        #[cfg(feature = "parallel")]
        for threads in [1, 4] {
            let executor = executor(threads);
            record(
                format!("component{bits}_executor_t{threads}"),
                CmgPreconditioner::build_component_experiment_with_executor(
                    graph, options, experiment, &executor,
                )
                .unwrap(),
            );
            record(
                format!("component{bits}_executor_budget_t{threads}"),
                CmgPreconditioner::build_component_experiment_with_executor_and_cmg_budget(
                    graph,
                    options,
                    experiment,
                    &executor,
                    usize::MAX,
                )
                .unwrap(),
            );
        }
    }
    #[cfg(all(feature = "parallel", feature = "profiling"))]
    {
        let executor = executor(4);
        let (preconditioner, _) =
            CmgPreconditioner::build_with_executor_profiled(graph, options, &executor).unwrap();
        record("build_executor_profiled_t4".into(), preconditioner);
    }
}

fn graphs(cases: &mut BTreeMap<String, u64>, name: &str, vertices: usize, edges: &[(usize, usize, f64)]) {
    let mut record = |case: &str, graph: Laplacian| {
        let mut digest = Digest::new();
        graph_digest(&mut digest, &graph);
        cases.insert(format!("{name}/graph_{case}"), digest.0);
    };
    record("from_edges", Laplacian::from_edges(vertices, edges.iter().copied()).unwrap());
    record(
        "controlled",
        Laplacian::from_edges_controlled(vertices, edges, usize::MAX, &|| false).unwrap(),
    );
    #[cfg(feature = "parallel")]
    for threads in [1, 4] {
        let executor = executor(threads);
        record(
            &format!("executor_t{threads}"),
            Laplacian::from_edges_with_executor(vertices, edges.iter().copied(), &executor)
                .unwrap(),
        );
        let pool = rayon::ThreadPoolBuilder::new()
            .num_threads(threads)
            .build()
            .unwrap();
        let graph = pool.install(|| {
            HostExecutor::new(&pool, threads)
                .unwrap()
                .with_installed(|team| {
                    Laplacian::from_edges_hosted_controlled(vertices, edges, usize::MAX, &team, &|| false)
                })
                .unwrap()
                .unwrap()
        });
        record(&format!("hosted_t{threads}"), graph);
    }
}

#[cfg(feature = "parallel")]
fn planned_cycles(
    cases: &mut BTreeMap<String, u64>,
    name: &str,
    graph: &Laplacian,
    preconditioner: &CmgPreconditioner,
) {
    for threads in [1, 4] {
        let executor = executor(threads);
        let plan = ParallelCmgPlan::build_with_budget(preconditioner, &executor, usize::MAX).unwrap();
        let mut digest = Digest::new();
        digest.usize(plan.operator_count());
        let mut workspace = preconditioner.try_workspace().unwrap();
        let mut output = vec![0.0; graph.vertex_count()];
        for seed in [1, 2] {
            plan.apply_compatible_into(
                preconditioner,
                &compatible_rhs(graph, seed),
                &mut output,
                &mut workspace,
                &executor,
            )
            .unwrap();
            digest.values(&output);
        }
        cases.insert(format!("{name}/plan_t{threads}"), digest.0);
        for capacity in 1..=4 {
            let mut batch = CmgBatchWorkspace::try_new(preconditioner, capacity, usize::MAX).unwrap();
            let n = graph.vertex_count();
            for columns in [1, capacity] {
                let mut rhs = vec![0.0; n * columns];
                for lane in 0..columns {
                    for (row, value) in compatible_rhs(graph, 10 + lane as u64).into_iter().enumerate() {
                        rhs[row * columns + lane] = value;
                    }
                }
                let mut serial = vec![0.0; n * columns];
                preconditioner
                    .apply_compatible_batch_into(&rhs, &mut serial, columns, &mut batch)
                    .unwrap();
                let mut planned = vec![0.0; n * columns];
                plan.apply_compatible_batch_into(
                    preconditioner,
                    &rhs,
                    &mut planned,
                    columns,
                    &mut batch,
                    &executor,
                )
                .unwrap();
                let mut digest = Digest::new();
                digest.values(&serial);
                cases.insert(
                    format!("{name}/batch_serial_c{capacity}_w{columns}_t{threads}"),
                    digest.0,
                );
                let mut digest = Digest::new();
                digest.values(&planned);
                cases.insert(
                    format!("{name}/batch_planned_c{capacity}_w{columns}_t{threads}"),
                    digest.0,
                );
            }
        }
    }
}

fn batch_inputs(graph: &Laplacian, count: usize) -> (Vec<f64>, Vec<f64>) {
    let n = graph.vertex_count();
    let mut rhs = Vec::with_capacity(n * count);
    let mut guess = Vec::with_capacity(n * count);
    for lane in 0..count {
        rhs.extend(compatible_rhs(graph, 30 + lane as u64));
        guess.extend((0..n).map(|i| ((i + lane) % 5) as f64 * 0.01));
    }
    (rhs, guess)
}

fn solves(
    cases: &mut BTreeMap<String, u64>,
    name: &str,
    graph: &Laplacian,
    stale: &Laplacian,
    preconditioner: &CmgPreconditioner,
) {
    let n = graph.vertex_count();
    let options = pcg_options();
    let rhs = compatible_rhs(graph, 21);
    let result = solve_pcg(graph, preconditioner, &rhs, options).unwrap();
    let mut digest = Digest::new();
    digest.values(result.solution());
    digest.diagnostics(result.diagnostics());
    cases.insert(format!("{name}/pcg"), digest.0);

    let mut workspace = PcgWorkspace::try_new(preconditioner).unwrap();
    let guess: Vec<_> = (0..n).map(|i| (i % 3) as f64 * 0.1).collect();
    let mut solution = vec![0.0; n];
    let diagnostics = solve_pcg_into_with_workspace(
        graph,
        preconditioner,
        &rhs,
        Some(&guess),
        &mut solution,
        options,
        &mut workspace,
    )
    .unwrap();
    let mut digest = Digest::new();
    digest.values(&solution);
    digest.diagnostics(diagnostics);
    cases.insert(format!("{name}/pcg_guess"), digest.0);

    let stale_rhs = compatible_rhs(stale, 22);
    let diagnostics = solve_pcg_with_retained_preconditioner_into_with_workspace(
        stale,
        preconditioner,
        &stale_rhs,
        None,
        &mut solution,
        options,
        &mut workspace,
    )
    .unwrap();
    let mut digest = Digest::new();
    digest.values(&solution);
    digest.diagnostics(diagnostics);
    cases.insert(format!("{name}/pcg_retained"), digest.0);

    let count = 3;
    let (batch_rhs, batch_guess) = batch_inputs(graph, count);
    let (stale_rhs, _) = batch_inputs(stale, count);
    let mut batch_workspace = PcgBatchWorkspace::new(preconditioner).unwrap();
    let mut run = |cases: &mut BTreeMap<String, u64>,
                   case: &str,
                   solve: &mut dyn FnMut(
        PcgBatchRef<'_>,
        Option<PcgBatchRef<'_>>,
        PcgBatchMut<'_>,
        &mut [PcgDiagnostics],
        &mut PcgBatchWorkspace,
    ) -> Result<(), CmgError>,
                   rhs: &[f64],
                   guesses: bool| {
        let mut solutions = vec![0.0; n * count];
        let mut diagnostics = vec![PcgDiagnostics::default(); count];
        solve(
            PcgBatchRef::contiguous(rhs, count, n).unwrap(),
            guesses.then(|| PcgBatchRef::contiguous(&batch_guess, count, n).unwrap()),
            PcgBatchMut::contiguous(&mut solutions, count, n).unwrap(),
            &mut diagnostics,
            &mut batch_workspace,
        )
        .unwrap();
        let mut digest = Digest::new();
        digest.values(&solutions);
        diagnostics.into_iter().for_each(|d| digest.diagnostics(d));
        cases.insert(format!("{name}/{case}"), digest.0);
    };
    run(
        cases,
        "batch_serial",
        &mut |rhs, guesses, solutions, diagnostics, workspace| {
            solve_pcg_batch_into_with_workspace(
                graph,
                preconditioner,
                rhs,
                guesses,
                solutions,
                diagnostics,
                options,
                workspace,
            )
        },
        &batch_rhs,
        true,
    );
    run(
        cases,
        "batch_serial_retained",
        &mut |rhs, guesses, solutions, diagnostics, workspace| {
            solve_pcg_batch_with_retained_preconditioner_into_with_workspace(
                stale,
                preconditioner,
                rhs,
                guesses,
                solutions,
                diagnostics,
                options,
                workspace,
            )
        },
        &stale_rhs,
        false,
    );
    #[cfg(feature = "parallel")]
    for threads in [1, 4] {
        let executor = executor(threads);
        let plan = ParallelCmgPlan::build_with_budget(preconditioner, &executor, usize::MAX).unwrap();
        run(
            cases,
            &format!("batch_planned_t{threads}"),
            &mut |rhs, guesses, solutions, diagnostics, workspace| {
                solve_pcg_batch_into_with_plan_and_workspace(
                    graph,
                    preconditioner,
                    &plan,
                    rhs,
                    guesses,
                    solutions,
                    diagnostics,
                    options,
                    workspace,
                    &executor,
                )
            },
            &batch_rhs,
            true,
        );
        run(
            cases,
            &format!("batch_planned_retained_t{threads}"),
            &mut |rhs, guesses, solutions, diagnostics, workspace| {
                solve_pcg_batch_with_plan_and_retained_preconditioner_into_with_workspace(
                    stale,
                    preconditioner,
                    &plan,
                    rhs,
                    guesses,
                    solutions,
                    diagnostics,
                    options,
                    workspace,
                    &executor,
                )
            },
            &stale_rhs,
            false,
        );
        let result = solve_pcg_with_plan(graph, preconditioner, &plan, &rhs, options, &executor)
            .unwrap();
        let mut digest = Digest::new();
        digest.values(result.solution());
        digest.diagnostics(result.diagnostics());
        cases.insert(format!("{name}/pcg_planned_t{threads}"), digest.0);
        let mut pool = PcgBatchWorkspace::new_bank_with_budget(preconditioner, 2, usize::MAX)
            .unwrap();
        for (case, current, inputs, guesses) in [
            ("batch_executor", graph, &batch_rhs, true),
            ("batch_executor_retained", stale, &stale_rhs, false),
        ] {
            let mut solutions = vec![0.0; n * count];
            let mut diagnostics = vec![PcgDiagnostics::default(); count];
            let rhs = PcgBatchRef::contiguous(inputs, count, n).unwrap();
            let guess = guesses.then(|| PcgBatchRef::contiguous(&batch_guess, count, n).unwrap());
            let solutions_view = PcgBatchMut::contiguous(&mut solutions, count, n).unwrap();
            if case == "batch_executor" {
                solve_pcg_batch_into_with_executor(
                    current,
                    preconditioner,
                    rhs,
                    guess,
                    solutions_view,
                    &mut diagnostics,
                    options,
                    &mut pool,
                    &executor,
                )
            } else {
                solve_pcg_batch_with_retained_preconditioner_into_with_executor(
                    current,
                    preconditioner,
                    rhs,
                    guess,
                    solutions_view,
                    &mut diagnostics,
                    options,
                    &mut pool,
                    &executor,
                )
            }
            .unwrap();
            let mut digest = Digest::new();
            digest.values(&solutions);
            diagnostics.into_iter().for_each(|d| digest.diagnostics(d));
            cases.insert(format!("{name}/{case}_t{threads}"), digest.0);
        }
        let owned: Vec<Vec<f64>> = batch_rhs.chunks(n).map(<[f64]>::to_vec).collect();
        for (case, results) in [
            (
                "batch_with_executor",
                solve_pcg_batch_with_executor(graph, preconditioner, &owned, options, &executor)
                    .unwrap(),
            ),
            (
                "batch_parallel",
                solve_pcg_batch_parallel(
                    graph,
                    preconditioner,
                    &owned,
                    options,
                    ParallelOptions {
                        threads,
                        min_parallel_len: 64,
                        reduction_chunk_size: 256,
                        ..ParallelOptions::default()
                    },
                )
                .unwrap(),
            ),
        ] {
            let mut digest = Digest::new();
            for result in results {
                digest.values(result.solution());
                digest.diagnostics(result.diagnostics());
            }
            cases.insert(format!("{name}/{case}_t{threads}"), digest.0);
        }
    }
    let owned: Vec<Vec<f64>> = batch_rhs.chunks(n).map(<[f64]>::to_vec).collect();
    let results = solve_pcg_batch(graph, preconditioner, &owned, options).unwrap();
    let mut digest = Digest::new();
    for result in results {
        digest.values(result.solution());
        digest.diagnostics(result.diagnostics());
    }
    cases.insert(format!("{name}/batch_owned"), digest.0);
}

#[cfg(feature = "parallel")]
fn policy_solver(cases: &mut BTreeMap<String, u64>, name: &str, graph: &Laplacian, options: CmgOptions) {
    let n = graph.vertex_count();
    let (batch_rhs, _) = batch_inputs(graph, 4);
    let owned: Vec<Vec<f64>> = batch_rhs.chunks(n).map(<[f64]>::to_vec).collect();
    for threads in [1, 4] {
        for policy in [
            ParallelPcgPolicy::default(),
            ParallelPcgPolicy {
                min_planned_edges: 1,
                min_across_rhs_concurrency: 2,
            },
            ParallelPcgPolicy {
                min_planned_edges: 1,
                min_across_rhs_concurrency: 64,
            },
        ] {
            let solver = ParallelPcgSolver::build_with_policy(
                graph,
                options,
                ParallelOptions {
                    threads,
                    min_parallel_len: 64,
                    reduction_chunk_size: 256,
                    ..ParallelOptions::default()
                },
                policy,
            )
            .unwrap();
            let mut digest = Digest::new();
            let single = solver.solve(&owned[0], pcg_options()).unwrap();
            digest.values(single.solution());
            digest.diagnostics(single.diagnostics());
            let batch = solver.solve_batch(&owned, pcg_options()).unwrap();
            digest.usize(batch.report().execution() as usize);
            digest.usize(batch.report().concurrency());
            for result in batch.results() {
                digest.values(result.solution());
                digest.diagnostics(result.diagnostics());
            }
            cases.insert(
                format!(
                    "{name}/policy_t{threads}_p{}_{}",
                    policy.min_planned_edges, policy.min_across_rhs_concurrency
                ),
                digest.0,
            );
        }
    }
}

fn prepared(cases: &mut BTreeMap<String, u64>, name: &str, vertices: usize, edges: &[(usize, usize, f64)]) -> (Laplacian, Laplacian) {
    let topology =
        PreparedLaplacianTopology::prepare(vertices, edges.iter().map(|&(u, v, _)| (u, v))).unwrap();
    let first: Vec<_> = edges.iter().map(|&(_, _, w)| w).collect();
    let second: Vec<_> = edges
        .iter()
        .enumerate()
        .map(|(index, &(_, _, w))| w * (1.0 + (index % 7) as f64 / 8.0))
        .collect();
    let mut workspace = topology.workspace().unwrap();
    let current = topology.assemble_with_workspace(&first, &mut workspace).unwrap();
    let stale = topology.assemble_with_workspace(&second, &mut workspace).unwrap();
    for (case, graph) in [("prepared_first", &current), ("prepared_second", &stale)] {
        let mut digest = Digest::new();
        graph_digest(&mut digest, graph);
        cases.insert(format!("{name}/{case}"), digest.0);
    }
    (current, stale)
}

fn sddm(cases: &mut BTreeMap<String, u64>) {
    let n = 40;
    let mut dense = vec![vec![0.0; n]; n];
    for i in 0..n {
        dense[i][i] = 2.5 + (i % 3) as f64 * 0.25;
        if i + 1 < n {
            dense[i][i + 1] = -1.0;
            dense[i + 1][i] = -1.0;
        }
        if i + 7 < n {
            dense[i][i + 7] = -0.25;
            dense[i + 7][i] = -0.25;
        }
    }
    let matrix = SddmMatrix::from_dense(&dense, ValidationOptions::default()).unwrap();
    let solver = SddmSolver::from_matrix(&matrix, options(8), ValidationOptions::default()).unwrap();
    let rhs: Vec<_> = (0..n).map(|i| (i as f64 * 0.37).sin()).collect();
    let result = solver.solve(&rhs, pcg_options()).unwrap();
    let mut digest = Digest::new();
    digest.values(result.solution());
    digest.usize(result.iterations());
    digest.f64(result.residual_norm());
    digest.f64(result.backward_error());
    cases.insert("sddm/solve".into(), digest.0);
}

#[cfg(feature = "experimental-components")]
fn component_pcg(cases: &mut BTreeMap<String, u64>, name: &str, graph: &Laplacian) {
    let experiment = ComponentPcgExperiment::build(graph, options(64)).unwrap();
    let mut workspace = experiment.workspace().unwrap();
    let rhs = compatible_rhs(graph, 41);
    let mut solution = vec![0.0; graph.vertex_count()];
    let diagnostics = experiment
        .solve_into(&rhs, None, &mut solution, pcg_options(), &mut workspace)
        .unwrap();
    let mut digest = Digest::new();
    digest.values(&solution);
    digest.diagnostics(diagnostics.original());
    if let Some(active) = diagnostics.active() {
        digest.diagnostics(active);
    }
    digest.usize(experiment.active_vertices());
    digest.usize(experiment.direct_vertices());
    cases.insert(format!("{name}/component_pcg"), digest.0);
}

fn measure() -> BTreeMap<String, u64> {
    let mut cases = BTreeMap::new();
    let fixtures = [
        ("chain", chain_edges(), 2),
        ("chain_direct", chain_edges(), 128),
        ("random", random_edges(3000, 12_000, 7), 64),
    ];
    for (name, (vertices, edges), threshold) in &fixtures {
        graphs(&mut cases, name, *vertices, edges);
        let (graph, stale) = prepared(&mut cases, name, *vertices, edges);
        builders(&mut cases, name, &graph, options(*threshold), false);
        let preconditioner = CmgPreconditioner::build(&graph, options(*threshold)).unwrap();
        #[cfg(feature = "parallel")]
        planned_cycles(&mut cases, name, &graph, &preconditioner);
        solves(&mut cases, name, &graph, &stale, &preconditioner);
        #[cfg(feature = "parallel")]
        policy_solver(&mut cases, name, &graph, options(*threshold));
        #[cfg(feature = "experimental-components")]
        {
            let component = CmgPreconditioner::build_component_experiment(
                &graph,
                options(*threshold),
                component_options(7),
            )
            .unwrap();
            let name = format!("{name}_component");
            #[cfg(feature = "parallel")]
            planned_cycles(&mut cases, &name, &graph, &component);
            solves(&mut cases, &name, &graph, &stale, &component);
            component_pcg(&mut cases, &name, &graph);
        }
    }
    sddm(&mut cases);
    // The large fixture exercises parallel setup thresholds; it is checked in
    // release builds, where its debug-mode cost would dominate the suite.
    if !cfg!(debug_assertions) {
        let (vertices, edges) = grid_edges(260, 262);
        graphs(&mut cases, "grid", vertices, &edges);
        let graph = Laplacian::from_edges(vertices, edges.iter().copied()).unwrap();
        builders(&mut cases, "grid", &graph, options(700), true);
        #[cfg(feature = "parallel")]
        {
            let preconditioner = CmgPreconditioner::build(&graph, options(700)).unwrap();
            planned_cycles(&mut cases, "grid", &graph, &preconditioner);
        }
    }
    cases
}

fn parse(text: &str) -> BTreeMap<String, BTreeMap<String, u64>> {
    let mut sections = BTreeMap::new();
    let mut current = None;
    for line in text.lines() {
        if let Some(name) = line.strip_prefix("[").and_then(|l| l.strip_suffix("]")) {
            current = Some(name.to_owned());
            sections.insert(name.to_owned(), BTreeMap::new());
        } else if let Some((case, value)) = line.split_once(' ') {
            let section = sections.get_mut(current.as_ref().unwrap()).unwrap();
            section.insert(case.to_owned(), u64::from_str_radix(value, 16).unwrap());
        }
    }
    sections
}

#[test]
fn consolidated_paths_reproduce_frozen_pre_consolidation_bits() {
    let section = format!(
        "{}{}",
        features(),
        if cfg!(debug_assertions) { "" } else { "+release" }
    );
    let measured = measure();
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(FIXTURE);
    let mut sections = std::fs::read_to_string(&path)
        .map(|text| parse(&text))
        .unwrap_or_default();
    if std::env::var_os("CMG_FROZEN_WRITE").is_some() {
        sections.insert(section, measured);
        let mut text = String::new();
        for (name, cases) in &sections {
            writeln!(text, "[{name}]").unwrap();
            for (case, value) in cases {
                writeln!(text, "{case} {value:016x}").unwrap();
            }
        }
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(&path, text).unwrap();
        return;
    }
    let expected = sections
        .get(&section)
        .unwrap_or_else(|| panic!("no frozen section [{section}]"));
    let mut mismatches = Vec::new();
    for (case, value) in &measured {
        match expected.get(case) {
            Some(frozen) if frozen == value => {}
            Some(frozen) => mismatches.push(format!("{case}: {frozen:016x} -> {value:016x}")),
            None => mismatches.push(format!("{case}: not frozen")),
        }
    }
    for case in expected.keys().filter(|case| !measured.contains_key(*case)) {
        mismatches.push(format!("{case}: frozen but not measured"));
    }
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}
